// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor, bytes32 g1, bytes32 g2) public {
        vm.assume(actor != address(0) && actor != address(c));

        // First guess is always accepted (paying exactly 1 ether).
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g1);

        // Advance blocks so the guess is not zero and the contract is in an active state.
        vm.roll(block.number + 5);

        // GENERAL RULE: while an address has an active guess, lockInGuess MUST revert
        // for that address, no matter the hash or value supplied.
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool ok;
        try c.lockInGuess{value: 1 ether}(g2) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok, "lockInGuess must revert while a guess is already locked in");
    }
}
